set -e
export LANG=C LC_ALL=C
D=/opt/lzh/v7re/work/mixed
rm -rf $D; mkdir -p $D; cd $D
base64 -d << 'EOB64' > /tmp/mixed.zip

EOB64
unzip -oq /tmp/mixed.zip -d $D
/opt/lzh/Xilinx/Vivado/2017.2/bin/vivado -mode batch -notrace -source _mixed.tcl > mixed.log 2>&1 || true
grep -E "DSP_SITES|DONE_mixed" mixed.log || true
